//! Entry point. On Android this becomes `libmain.so` loaded by the
//! NativeActivity generated by cargo-apk; on desktop it runs the same eframe
//! app in a window for rapid iteration.

use std::path::PathBuf;

use eframe::egui::ViewportBuilder;

use gear_compat::db::Database;
use gear_compat::ui::GearCompatApp;

/// Locate the writable app directory.
///
/// On Android we log the manifest path reported by `ndk-context` (proving the
/// native activity is attached) and use the standard app-private files dir
/// `/data/data/<package>/files`, which requires no storage permission.
/// On desktop the DB lives under `./data`.
fn resolve_data_dir() -> PathBuf {
    #[cfg(target_os = "android")]
    {
        let ctx = ndk_context::android_context();
        log::info!(
            "android context: manifest={}, class_loader={}",
            ctx.manifest_path(),
            ctx.class_loader()
        );
        // Matches `[package.metadata.android] package` in Cargo.toml.
        PathBuf::from("/data/data/com.gearcompat.rust/files")
    }
    #[cfg(not(target_os = "android"))]
    {
        PathBuf::from("./data")
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    #[cfg(target_os = "android")]
    {
        // Route every log line into logcat so crashes/DB errors are visible via
        // `adb logcat -s gear_compat`.
        android_logger::init_once(
            android_logger::Config::default()
                .with_max_level(log::LevelFilter::Debug)
                .with_tag("gear_compat"),
        );
    }

    let data_dir = resolve_data_dir();
    log::info!("opening local database in {}", data_dir.display());

    // First launch creates + seeds the SQLite file; later launches reuse it.
    let db = Database::open_in_dir(&data_dir)?;
    gear_compat::set_android_data_dir(data_dir.clone());

    let options = eframe::NativeOptions {
        viewport: ViewportBuilder::default()
            .with_title("Gear Compat")
            .with_inner_size([420.0, 760.0])
            .with_app_id("com.gearcompat.rust"),
        renderer: eframe::Renderer::Glow,
        ..Default::default()
    };

    eframe::run_native(
        "Gear Compat",
        options,
        Box::new(move |_cc| Ok(Box::new(GearCompatApp::new(db)))),
    )?;

    Ok(())
}
